# Please respect the MCnet Guidelines, see GUIDELINES for details.

Render a validated FeynRulesModel (frmodel.py) to a FeynRules ``.fr`` file.

The fiddly Mathematica syntax (association comma placement, ``->`` vs ``:>``,
mass tuples, ``Index[...]`` wrapping, rationals) is built here in tested Python;
a thin Jinja2 template (templates/model.fr.j2) supplies the file skeleton.
"""

from __future__ import annotations

import os
from typing import List, Optional, Sequence, Tuple

from jinja2 import Environment, FileSystemLoader, select_autoescape

from .frmodel import (
    FeynRulesModel,
    GaugeGroup,
    IndexDecl,
    MassSpec,
    Parameter,
    ParticleClass,
)

_TEMPLATE_DIR = os.path.join(os.path.dirname(__file__), "templates")


# --------------------------- scalar helpers --------------------------- #


def _bool(b: bool) -> str:
    return "True" if b else "False"


def _quote(s: str) -> str:
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _strlist(items: Sequence[str]) -> str:
    """M$Information-style: single -> "x"; many -> {"x", "y"}."""
    if len(items) == 1:
        return _quote(items[0])
    return "{" + ", ".join(_quote(x) for x in items) + "}"


def _name_field(v) -> str:
    """ParticleName/FullName/PropagatorLabel: str -> quoted; list -> {...}."""
    if isinstance(v, list):
        return "{" + ", ".join(_quote(x) for x in v) + "}"
    return _quote(v)


def _pdg(v) -> str:
    if isinstance(v, list):
        return "{" + ", ".join(str(x) for x in v) + "}"
    return str(v)


def _indices(names: Sequence[str]) -> str:
    return "{" + ", ".join(f"Index[{n}]" for n in names) + "}"


# FeynRules QuantumNumbers holds only additive (U(1)-type) charges. Colour/SU2/
# etc. are REPRESENTATION labels fixed by a field's Indices, not quantum numbers;
# if left in QuantumNumbers, FeynRules emits an unevaluated `Colour[field]` into
# the UFO's particles.py, which MadGraph rejects with "name 'Colour' is not
# defined". Drop these reserved index/representation names.
_REP_LABELS = {
    "Colour", "Color", "Sextet", "Gluon", "Generation", "Spin", "Lorentz",
    "SU2", "SU2W", "SU2L", "SU2D", "SU2R",
}


def _additive_qns(d: dict) -> dict:
    return {k: v for k, v in d.items() if k not in _REP_LABELS}


def _reserved_mass_width_names(particles) -> set:
    """Mass/width parameter names FeynRules auto-declares from particle Mass/Width
    specs. Declaring them again in M$Parameters double-defines the name in the UFO
    (MadGraph InvalidModel), so the renderer drops those duplicates."""
    names: set = set()
    for p in particles or []:
        for spec in (getattr(p, "mass", None), getattr(p, "width", None)):
            if spec is None:
                continue
            if getattr(spec, "sym", None):
                names.add(spec.sym)
            for sub, _val in (getattr(spec, "members", None) or []):
                names.add(sub)
    return names


def _is_internal_param(p) -> bool:
    """Internal/derived parameters carry a formula (Definitions) that FeynRules
    cannot auto-create from a particle Mass/Width spec, so they must stay in
    M$Parameters even when named like a mass/width (e.g. a computed decay width
    Width -> {WV1, Internal}). Only plain External duplicates are dropped."""
    if getattr(p, "definitions", None):
        return True
    return "internal" in str(getattr(p, "parameter_type", "")).lower()


def _qn(d: dict) -> str:
    return "{" + ", ".join(f"{k} -> {v}" for k, v in _additive_qns(d).items()) + "}"


def _interaction_order(t: Tuple[str, int]) -> str:
    return f"{{{t[0]}, {t[1]}}}"


def _mw_value(v):
    """Normalize a mass/width value. FeynRules' ``Automatic`` width is computed
    only when AddDecays is on — which is off for us (broken on Wolfram >=15), so
    it leaks the literal ``Automatic`` into the UFO and MadGraph fails with
    ``name 'Automatic' is not defined``. Emit a numeric placeholder instead;
    MadGraph's compute_widths recovers the real width from the model."""
    return "1." if str(v).strip().lower() == "automatic" else v


def _mass(m: MassSpec) -> str:
    if m.massless:
        return "0"
    if m.members:
        parts = [m.sym]
        for sub, val in m.members:
            val = _mw_value(val)
            parts.append(f"{{{sub}, {val}}}" if val is not None else f"{{{sub}}}")
        return "{" + ", ".join(parts) + "}"
    if m.value is not None:
        return f"{{{m.sym}, {_mw_value(m.value)}}}"
    return f"{{{m.sym}}}"


def _reps(reps: Sequence[Tuple[str, str]]) -> str:
    if len(reps) == 1:
        r, s = reps[0]
        return f"{{{r}, {s}}}"
    return "{" + ", ".join(f"{{{r}, {s}}}" for r, s in reps) + "}"


def _assoc(pairs: List[Tuple[str, Optional[str]]], indent: str = "    ") -> str:
    """Render ``{ Key -> val, ... }``, dropping entries whose value is None."""
    kept = [(k, v) for k, v in pairs if v is not None]
    if not kept:
        return "{}"
    inner = ",\n".join(f"{indent}{k} -> {v}" for k, v in kept)
    close_indent = indent[:-2] if len(indent) >= 2 else ""
    return "{\n" + inner + "\n" + close_indent + "}"


# ------------------------------ blocks ------------------------------- #


def render_information(info) -> str:
    pairs = [
        ("Authors", _strlist(info.authors)),
        ("Version", _quote(info.version)),
        ("Date", _quote(info.date)),
        ("Institutions", _strlist(info.institutions) if info.institutions else None),
        ("Emails", _strlist(info.emails) if info.emails else None),
    ]
    return "M$Information = " + _assoc(pairs, indent="  ") + ";"


def _render_gauge_group(g: GaugeGroup) -> str:
    pairs: List[Tuple[str, Optional[str]]] = [
        ("Abelian", _bool(g.abelian)),
        ("CouplingConstant", g.coupling_constant),
        ("GaugeBoson", g.gauge_boson),
        ("Charge", g.charge),
        ("StructureConstant", g.structure_constant),
        ("Representations", _reps(g.representations) if g.representations else None),
        ("SymmetricTensor", g.symmetric_tensor),
        (
            "Definitions",
            ("{" + ", ".join(g.definitions) + "}") if g.definitions else None,
        ),
    ]
    return f"  {g.name} == " + _assoc(pairs, indent="    ")


def render_gauge_groups(groups: List[GaugeGroup]) -> str:
    entries = ",\n".join(_render_gauge_group(g) for g in groups)
    return "M$GaugeGroups = {\n" + entries + "\n};"


def render_index_decls(decls: List[IndexDecl]) -> str:
    lines: List[str] = []
    for d in decls:
        if d.range_kind.value == "Range":
            rng = f"Range[{d.size}]"
        else:
            rng = f"{d.range_kind.value}[Range[{d.size}]]"
        lines.append(f"IndexRange[Index[{d.name}]] = {rng};")
    for d in decls:
        if d.style_symbol:
            lines.append(f"IndexStyle[{d.name}, {d.style_symbol}];")
    return "\n".join(lines)


def _render_parameter(p: Parameter) -> str:
    pairs: List[Tuple[str, Optional[str]]] = [
        ("ParameterType", p.parameter_type.value if p.parameter_type else None),
    ]
    if p.is_tensor:
        pairs.append(
            (
                "Value",
                ("{" + ", ".join(r.render() for r in p.value_rules) + "}")
                if p.value_rules
                else None,
            )
        )
        pairs.append(("Indices", _indices(p.indices)))
    else:
        pairs.append(("Value", p.value))
    pairs += [
        ("ComplexParameter", _bool(p.complex) if p.complex is not None else None),
        ("BlockName", p.block_name),
        ("OrderBlock", str(p.order_block) if p.order_block is not None else None),
        (
            "InteractionOrder",
            _interaction_order(p.interaction_order) if p.interaction_order else None,
        ),
        (
            "Definitions",
            ("{" + ", ".join(r.render() for r in p.definitions) + "}")
            if p.definitions
            else None,
        ),
        ("ParameterName", p.parameter_name),
        ("TensorClass", p.tensor_class),
        ("Unitary", _bool(p.unitary) if p.unitary is not None else None),
        ("Hermitian", _bool(p.hermitian) if p.hermitian is not None else None),
        ("Orthogonal", _bool(p.orthogonal) if p.orthogonal is not None else None),
        (
            "AllowSummation",
            _bool(p.allow_summation) if p.allow_summation is not None else None,
        ),
        # TeX is a LaTeX label; render it as a quoted Mathematica string with
        # backslashes escaped ("\\Gamma_U"), else a raw value like \Gamma_U is a
        # Mathematica syntax error that aborts the whole M$Parameters block.
        ("TeX", _quote(p.tex) if p.tex else None),
        ("Description", _quote(p.description) if p.description else None),
    ]
    return f"  {p.name} == " + _assoc(pairs, indent="    ")


def render_parameters(params: List[Parameter]) -> str:
    entries = ",\n".join(_render_parameter(p) for p in params)
    return "M$Parameters = {\n" + entries + "\n};"


def _render_particle(p: ParticleClass) -> str:
    pairs: List[Tuple[str, Optional[str]]] = [
        ("ClassName", p.class_name),
        ("SelfConjugate", _bool(p.self_conjugate)),
        (
            "ClassMembers",
            ("{" + ", ".join(p.class_members) + "}") if p.class_members else None,
        ),
        ("Indices", _indices(p.indices) if p.indices else None),
        ("FlavorIndex", p.flavor_index),
        ("Mass", _mass(p.mass) if p.mass else None),
        ("Width", _mass(p.width) if p.width else None),
        ("QuantumNumbers",
         _qn(p.quantum_numbers) if _additive_qns(p.quantum_numbers or {}) else None),
        ("PDG", _pdg(p.pdg) if p.pdg is not None else None),
        ("ParticleName", _name_field(p.particle_name) if p.particle_name else None),
        (
            "AntiParticleName",
            _name_field(p.antiparticle_name) if p.antiparticle_name else None,
        ),
        ("FullName", _name_field(p.full_name) if p.full_name else None),
        (
            "PropagatorLabel",
            _name_field(p.propagator_label) if p.propagator_label else None,
        ),
        ("PropagatorType", p.propagator_type.value if p.propagator_type else None),
        ("PropagatorArrow", p.propagator_arrow.value if p.propagator_arrow else None),
        ("Ghost", p.ghost),
        ("Goldstone", p.goldstone),
        ("Chirality", p.chirality),
        ("MajoranaPhase", p.majorana_phase),
        (
            "WeylComponents",
            ("{" + ", ".join(p.weyl_components) + "}") if p.weyl_components else None,
        ),
        ("Unphysical", _bool(True) if p.unphysical else None),
        (
            "Definitions",
            ("{" + ", ".join(p.definitions) + "}") if p.definitions else None,
        ),
    ]
    return f"  {p.class_label} == " + _assoc(pairs, indent="    ")


def render_classes(particles: List[ParticleClass]) -> str:
    entries = ",\n".join(_render_particle(p) for p in particles)
    return "M$ClassesDescription = {\n" + entries + "\n};"


def render_model(model: FeynRulesModel) -> str:
    """Render a validated FeynRulesModel to a complete ``.fr`` string."""
    sections: List[str] = [render_information(model.info)]

    if model.interaction_order_hierarchy:
        ih = ", ".join(_interaction_order(t) for t in model.interaction_order_hierarchy)
        sections.append("M$InteractionOrderHierarchy = {" + ih + "};")
    if model.interaction_order_limit:
        il = ", ".join(_interaction_order(t) for t in model.interaction_order_limit)
        sections.append("M$InteractionOrderLimit = {" + il + "};")
    if model.feynman_gauge is not None:
        sections.append(f"FeynmanGauge = {_bool(model.feynman_gauge)};")
    if model.vevs:
        vv = ", ".join(f"{{{f}, {v}}}" for f, v in model.vevs)
        sections.append("M$vevs = {" + vv + "};")

    for raw in model.raw_preamble:
        sections.append(raw)

    if model.index_decls:
        sections.append(render_index_decls(model.index_decls))
    if model.gauge_groups:
        sections.append(render_gauge_groups(model.gauge_groups))
    if model.parameters:
        # FeynRules auto-declares the mass/width parameters named in each
        # particle's Mass/Width spec. Re-declaring them in M$Parameters makes the
        # UFO define the name twice, which MadGraph rejects ("name X define
        # multiple time"). Drop those duplicates; keep genuine couplings.
        reserved = _reserved_mass_width_names(model.particles)
        params = [p for p in model.parameters
                  if p.name not in reserved or _is_internal_param(p)]
        if params:
            sections.append(render_parameters(params))
    if model.particles:
        sections.append(render_classes(model.particles))
    for field, expr in model.gauge_xi:
        sections.append(f"GaugeXi[{field}] = {expr};")

    for raw in model.raw_blocks:
        sections.append(raw)

    for t in model.lagrangian_terms:
        op = ":=" if t.delayed else "="
        # Defensive: some (LLM-produced) expressions already carry a leading
        # assignment operator ("= ..." or ":= ..."); strip it so we don't emit a
        # duplicated operator (e.g. "L := := Block[...]").
        rhs = t.expression.lstrip()
        for lead in (":=", "="):
            if rhs.startswith(lead):
                rhs = rhs[len(lead):].lstrip()
                break
        sections.append(f"{t.name} {op} {rhs};")

    env = Environment(
        loader=FileSystemLoader(_TEMPLATE_DIR),
        autoescape=select_autoescape(enabled_extensions=(), default=False),
        keep_trailing_newline=True,
    )
    template = env.get_template("model.fr.j2")
    return template.render(model_name=model.model_name, body="\n\n".join(sections))

#!/usr/bin/env python3
"""Deterministic lints for an agent-written FeynRules add-on (.fr) file.

Every rule encodes one construct that broke a compile, a FeynRules check or a
MadGraph import in the benchmark (prompt_addendum_v3.txt rules 9-15 and the
repair-loop taxonomy). A lint runs in milliseconds on the text; the compile it
predicts takes up to 900 s.

Each finding carries the STAGE it predicts:
  compile  - FeynRules will not load or will not finish the model
  checks   - the model loads but a consistency check fails
  mg5      - the UFO is written but MadGraph rejects it
  harness  - the validation harness cannot pick the total Lagrangian
  warn     - FeynRules warns; the run may still pass

Library: ``lint_text(text) -> list[Finding]``. CLI: ``fr_lint.py file.fr``.
"""

from __future__ import annotations

import json
import re
import sys
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Dict, List, Optional, Set

HEPTAPOD = Path.home() / "Documents/Github/heptapod"
SM_FR = HEPTAPOD / "tools/feynrules/test_files/models/SM.fr"

# Mathematica built-ins and FeynRules symbols a class, parameter or index must
# not be named after (rule 10).
FR_SYMBOLS = {"HC", "CC", "FS", "DC", "del", "Eps", "Ga", "ProjP", "ProjM", "T",
              "Sig", "PauliSigma", "IndexDelta", "ME", "Index", "Indices", "Mass",
              "Width", "Value", "Unphysical", "Abelian"}
PROTECTED = {"N", "C", "D", "E", "I", "K", "O", "Pi", "Gamma", "Beta", "Zeta",
             "Sqrt", "Exp", "Log", "Sin", "Cos", "Tan", "Re", "Im", "Conjugate",
             "Sum", "Block", "Module", "Table", "If", "Which"}

# Names SM.fr declares: classes, class members, parameters, gauge groups, indices.
_SM_TEXT = SM_FR.read_text() if SM_FR.is_file() else ""
SM_CLASSES: Set[str] = set(re.findall(r"ClassName\s*->\s*(\w+)", _SM_TEXT))
SM_MEMBERS: Set[str] = set()
for _m in re.findall(r"ClassMembers\s*->\s*\{([^}]*)\}", _SM_TEXT):
    SM_MEMBERS |= {x.strip() for x in _m.split(",") if x.strip()}
_i = _SM_TEXT.find("M$Parameters")
SM_PARAMS: Set[str] = set(re.findall(r"^\s*(\w+)\s*==\s*\{", _SM_TEXT[_i:], re.M)) if _i >= 0 else set()
SM_GAUGE = {"U1Y", "SU2L", "SU3C"}
SM_INDICES = {"Generation", "Colour", "Gluon", "SU2D", "SU2W", "Lorentz", "Spin",
              "Spin1", "Spin2", "Sextet"}
SM_FIELDS_ALL = SM_CLASSES | SM_MEMBERS | {c + "bar" for c in SM_CLASSES | SM_MEMBERS}
SM_MASSES = {"MZ", "MW", "MH", "Me", "MMU", "MTA", "MU", "MC", "MT", "MD", "MS", "MB",
             "WZ", "WW", "WH", "WT"}

FR_BUILTINS = {"HC", "CC", "FS", "DC", "del", "Eps", "Ga", "ProjP", "ProjM", "T",
               "PauliSigma", "IndexDelta", "ME", "Sqrt", "Exp", "Log", "Sin", "Cos",
               "Tan", "I", "Pi", "Sum", "Block", "Module", "ExpandIndices",
               "FlavorExpand", "True", "False", "bar", "anti", "left", "right",
               "Conjugate", "Re", "Im", "Abs", "Sig", "Ta", "T6", "K6", "K6bar",
               "K3", "K3bar", "f", "dSUN", "Dot", "Times", "Plus", "Power",
               "Automatic", "Internal", "External", "Unfold", "NoUnfold", "Range",
               "Index", "Lorentz", "Spin", "Colour", "Gluon", "Generation",
               "SU2D", "SU2W", "Sextet", "IndexStyle", "MakeIdenticalFermions",
               "Expand", "Simplify", "ProjPlus", "ProjMinus", "FR$", "vev"}


@dataclass
class Finding:
    rule: str
    stage: str  # compile | checks | mg5 | harness | warn
    message: str
    line: Optional[int] = None


# ------------------------------------------------------------------ parsing

def strip_comments(text: str) -> str:
    out, depth, i = [], 0, 0
    while i < len(text):
        if text.startswith("(*", i):
            depth += 1
            i += 2
            continue
        if text.startswith("*)", i) and depth:
            depth -= 1
            i += 2
            continue
        if depth == 0:
            out.append(text[i])
        elif text[i] == "\n":
            out.append("\n")
        i += 1
    return "".join(out)


def _matching(text: str, open_idx: int) -> int:
    depth = 0
    pairs = {"{": "}", "[": "]", "(": ")"}
    closes = set(pairs.values())
    for j in range(open_idx, len(text)):
        ch = text[j]
        if ch in pairs:
            depth += 1
        elif ch in closes:
            depth -= 1
            if depth == 0:
                return j
    return len(text) - 1


def _block(text: str, name: str) -> str:
    m = re.search(rf"M\${name}\s*=\s*\{{", text)
    if not m:
        return ""
    end = _matching(text, m.end() - 1)
    return text[m.end():end]


def _entries(block: str) -> List[Dict]:
    """Top-level `Head == { ... }` entries of a M$ block."""
    out = []
    for m in re.finditer(r"(\w+(?:\[\s*\d+\s*\])?)\s*==\s*\{", block):
        end = _matching(block, m.end() - 1)
        body = block[m.end():end]
        out.append({"head": m.group(1), "body": body, "pos": m.start()})
    return out


def _prop(body: str, key: str) -> Optional[str]:
    m = re.search(rf"\b{key}\s*->\s*", body)
    if not m:
        return None
    rest = body[m.end():]
    if rest.startswith("{"):
        return rest[: _matching(rest, 0) + 1]
    mm = re.match(r"[^,}\n]+", rest)
    return mm.group(0).strip() if mm else None


def _is_kin_name(name: str) -> bool:
    return bool(re.search(r"kin|Kin|KIN|free|Free|Gauge|gauge", name))


def term_defs(text: str) -> List[Dict]:
    starts = [(m.group(1), m.start()) for m in re.finditer(r"^(L\w+)\s*:?=", text, re.M)]
    stops = [m.start() for m in re.finditer(r"^(?:M\$\w+\s*=|L\w+\s*:?=|\w+\s*=\s*\{)", text, re.M)]
    out = []
    for name, s in starts:
        e = min([x for x in stops if x > s] + [len(text)])
        out.append({"name": name, "body": text[s:e], "line": text[:s].count("\n") + 1})
    return out


def _line_of(text: str, needle: str) -> Optional[int]:
    i = text.find(needle)
    return text[:i].count("\n") + 1 if i >= 0 else None


# -------------------------------------------------------------------- lints

def lint_text(raw: str) -> List[Finding]:
    text = strip_comments(raw)
    F: List[Finding] = []
    classes = _entries(_block(text, "ClassesDescription"))
    params = _entries(_block(text, "Parameters"))
    terms = term_defs(text)
    term_names = {t["name"] for t in terms}
    term_bodies = "\n".join(t["body"] for t in terms)

    class_names, class_idx = {}, {}
    for c in classes:
        cn = _prop(c["body"], "ClassName")
        if cn:
            class_names[cn] = c
            mi = re.match(r"(\w+)\[\s*(\d+)\s*\]", c["head"])
            if mi:
                class_idx[cn] = (mi.group(1), int(mi.group(2)))
    param_names = {p["head"]: p for p in params}
    index_decls = dict(re.findall(r"IndexRange\[\s*Index\[(\w+)\]\s*\]\s*=\s*([^;\n]+)", text))

    # --- rule 10: names -------------------------------------------------
    for name in list(class_names) + list(param_names) + list(index_decls):
        if name in FR_SYMBOLS:
            F.append(Finding("feynrules_symbol_name", "compile",
                             f"`{name}` is a FeynRules symbol", _line_of(text, name)))
        elif name in PROTECTED:
            F.append(Finding("protected_name", "warn",
                             f"`{name}` is a Mathematica built-in (loads with a warning; renaming is safer)",
                             _line_of(text, name)))
    for name in class_names:
        if name in SM_CLASSES or name in SM_MEMBERS:
            F.append(Finding("sm_class_redeclared", "warn",
                             f"class `{name}` is already declared by SM.fr (doubly-defined class)",
                             _line_of(text, f"ClassName -> {name}")))
    for name in param_names:
        if name in SM_PARAMS or name in SM_MASSES:
            F.append(Finding("sm_parameter_redeclared", "warn",
                             f"parameter `{name}` is already declared by SM.fr", _line_of(text, name)))
    for cn, c in class_names.items():
        for key in ("ParticleName", "AntiParticleName"):
            v = _prop(c["body"], key)
            names = re.findall(r'"([^"]*)"', v) if v else []
            if v and any(re.search(r"[\'`\s!@#%^&*()=\[\]{}|\\;:<>?/,]", nm) for nm in names):
                F.append(Finding("bad_particle_name", "mg5",
                                 f"class `{cn}`: {key} {v} is not a valid UFO identifier", _line_of(text, v)))
        if cn in class_idx and class_idx[cn][1] < 100:
            F.append(Finding("low_class_index", "warn",
                             f"class `{cn}` uses index {class_idx[cn][0]}[{class_idx[cn][1]}]; SM.fr uses the low indices",
                             _line_of(text, c["head"])))
        for m in re.finditer(r"ClassMembers\s*->\s*\{([^}]*)\}", c["body"]):
            for mem in [x.strip() for x in m.group(1).split(",") if x.strip()]:
                if mem in SM_MEMBERS or mem in SM_CLASSES:
                    F.append(Finding("sm_member_redeclared", "compile",
                                     f"class member `{mem}` of `{cn}` collides with an SM.fr name",
                                     _line_of(text, mem)))
    if "$" in re.sub(r"M\$\w+", "", text):
        for m in re.finditer(r"\b\w*\$\w*", text):
            if not re.match(r"^(M|MR|FR)\$", m.group(0)):
                F.append(Finding("dollar_in_name", "mg5", f"`{m.group(0)}` contains `$` (invalid Python)",
                                 text[:m.start()].count("\n") + 1))
                break

    # --- rule 11: interaction orders --------------------------------------
    hierarchy = _block(text, "InteractionOrderHierarchy")
    orders_declared = set(re.findall(r"\{\s*(\w+)\s*,\s*-?\d+\s*\}", hierarchy))
    for pn, p in param_names.items():
        body = p["body"]
        ptype = (_prop(body, "ParameterType") or "External").strip()
        io = _prop(body, "InteractionOrder")
        used = re.search(rf"\b{re.escape(pn)}\b", term_bodies) is not None
        is_mass = any(re.search(rf"Mass\s*->\s*\{{\s*{re.escape(pn)}\b", c["body"]) or
                      re.search(rf"Width\s*->\s*\{{\s*{re.escape(pn)}\b", c["body"])
                      for c in classes) or re.match(r"^(M|W)[A-Z]", pn) and not io
        if io:
            oname = re.findall(r"\{\s*(\w+)\s*,", io)
            for o in oname:
                if o not in orders_declared and o not in ("QCD", "QED"):
                    F.append(Finding("order_not_in_hierarchy", "warn",
                                     f"parameter `{pn}` uses InteractionOrder `{o}` not listed in M$InteractionOrderHierarchy",
                                     _line_of(text, pn)))
    ordered = {pn for pn, p in param_names.items() if _prop(p["body"], "InteractionOrder")}
    internal = {pn for pn, p in param_names.items()
                if (_prop(p["body"], "ParameterType") or "External").strip() == "Internal"}
    # an Internal parameter inherits the orders of the parameters in its Value
    for pn in list(internal):
        val = _prop(param_names[pn]["body"], "Value") or ""
        if any(re.search(rf"\b{re.escape(o)}\b", val) for o in ordered):
            ordered.add(pn)
    for t in terms:
        if _is_kin_name(t["name"]):
            continue
        used_params = {pn for pn in param_names if re.search(rf"\b{re.escape(pn)}\b", t["body"])}
        sm_couplings = {"ee", "gw", "gs", "g1", "yl", "yu", "yd", "lam", "CKM"}
        if used_params and not (used_params & ordered) and not \
                any(re.search(rf"\b{c}\b", t["body"]) for c in sm_couplings) and \
                not any(re.search(rf"\b(DC|FS)\[", t["body"]) for _ in [0]):
            F.append(Finding("missing_interaction_order", "mg5",
                             f"`{t['name']}`: none of its parameters ({', '.join(sorted(used_params))}) carries an InteractionOrder",
                             t["line"]))

    # --- rule 12: pattern rules on tensor parameters -----------------------
    for pn, p in param_names.items():
        if re.search(r"\w+\[[^\]]*_[^\]]*\]\s*:?->", p["body"]) or "_?NumericQ" in p["body"]:
            F.append(Finding("pattern_rule_definition", "mg5",
                             f"parameter `{pn}` uses a pattern rule in Definitions/Value; FeynRules exports it verbatim as a UFO name",
                             _line_of(text, pn)))
    for cn, c in class_names.items():
        d = _prop(c["body"], "Definitions") or ""
        if re.search(r"\w+\[[^\]]*_[^\]]*\]\s*:>", d) and not re.search(r"\w+\[[^\]]*_\s*[,\]]", d):
            pass  # `X[mu_] :> ...` is the normal FeynRules idiom; leave it

    # --- rule 13: explicit indices ------------------------------------------
    for t in terms:
        b = t["body"]
        for m in re.finditer(r"DC\[\s*(\w+)\[([^\]]*)\]\s*,", b):
            fld = m.group(1)
            c = class_names.get(fld)
            idx = (_prop(c["body"], "Indices") or "") if c else ""
            if c and re.search(r"Colour|Sextet|Gluon|Octet|Col", idx):
                F.append(Finding("explicit_index_in_dc", "compile",
                                 f"`{t['name']}`: covariant derivative on `{fld}` with an explicit colour-type index", t["line"]))
            else:
                F.append(Finding("explicit_index_in_dc", "warn",
                                 f"`{t['name']}`: covariant derivative on an explicitly indexed field `{fld}`", t["line"]))
            break
        if re.search(r"Index\[\s*Generation\s*,\s*\w+\s*\]\s*,\s*Index\[\s*Generation", b) or \
                re.search(r"\w+\[\s*Generation\s*,\s*\w+\s*\]", b):
            F.append(Finding("nested_generation_index", "compile",
                             f"`{t['name']}`: nested generation index", t["line"]))
        m = re.search(r"\b(\w+)\[\s*(ff\d?|gen\d?|ii\d?)\s*,\s*(ff\d?|gen\d?|jj\d?)\s*\]\s*\w+bar\[", b)
        if m and m.group(1) in param_names:
            F.append(Finding("explicit_flavour_sum", "mg5",
                             f"`{t['name']}`: flavour matrix `{m.group(1)}` with explicit generation indices instead of matrix form",
                             t["line"]))

    # --- rule 14: one declared total ---------------------------------------
    roots = []
    for t in terms:
        if not any(re.search(rf"\b{t['name']}\b", u["body"]) for u in terms if u is not t):
            roots.append(t["name"])
    if terms and not roots:
        F.append(Finding("no_total_lagrangian", "harness", "no Lagrangian symbol is a root (circular or empty)", None))
    elif len(roots) > 1:
        F.append(Finding("ambiguous_total", "harness",
                         f"{len(roots)} root Lagrangian symbols: {', '.join(roots)}", None))
    elif roots and roots[0] not in ("LTotal", "LTot", "LFull", "LBSM", "LNP", "Lag", "LagTot"):
        F.append(Finding("total_not_named_ltotal", "warn", f"the single root is `{roots[0]}`, not LTotal", None))
    field_tokens = set(class_names) | {c + "bar" for c in class_names} | SM_FIELDS_ALL
    for c in classes:
        for m in re.finditer(r"ClassMembers\s*->\s*\{([^}]*)\}", c["body"]):
            field_tokens |= {x.strip() for x in m.group(1).split(",") if x.strip()}
    for t in terms:
        rhs = t["body"].split("=", 1)[-1]
        if re.search(r"\bL\w+\b", rhs) and any(re.search(rf"\b{u['name']}\b", rhs) for u in terms if u is not t):
            continue  # a sum of other terms
        if not any(re.search(rf"\b{re.escape(f)}\b", rhs) for f in field_tokens):
            F.append(Finding("fieldless_term", "mg5", f"`{t['name']}` contains no field", t["line"]))

    # --- rule 15: declarations -----------------------------------------------
    for cn, c in class_names.items():
        sc = (_prop(c["body"], "SelfConjugate") or "").strip()
        qn = _prop(c["body"], "QuantumNumbers")
        if sc == "True" and qn and re.search(r"->\s*-?[1-9]", qn):
            F.append(Finding("selfconjugate_with_qn", "warn",
                             f"class `{cn}` is SelfConjugate and carries QuantumNumbers {qn}",
                             _line_of(text, f"ClassName -> {cn}")))
        if sc == "True" and _prop(c["body"], "AntiParticleName"):
            pass
    # Majorana mass normalisation
    for cn, c in class_names.items():
        if (_prop(c["body"], "SelfConjugate") or "").strip() == "True" and c["head"].startswith("F"):
            mm = re.search(r"Mass\s*->\s*\{\s*(\w+)", c["body"])
            if not mm:
                continue
            M = mm.group(1)
            pat = re.compile(rf"(-?\s*(?:1/2|0\.5|\(1/2\))?\s*\*?\s*{M}\b[^;]{{0,40}}{cn}bar\s*\.\s*{cn}\b)")
            for t in terms:
                for hit in pat.finditer(t["body"]):
                    if not re.search(r"1/2|0\.5", hit.group(1)):
